        cast(source_fund_id as {{ dpf_type('string') }}) as vehicle_fund_source_id,
        cast(source_parent_vehicle_id as {{ dpf_type('string') }}) as vehicle_parent_source_id,
        cast(source_name as {{ dpf_type('string') }}) as vehicle_name,
        cast(source_vehicle_type as {{ dpf_type('string') }}) as vehicle_type,
        cast(source_jurisdiction as {{ dpf_type('string') }}) as vehicle_jurisdiction,
        cast(source_incorporated_on as {{ dpf_type('date') }}) as vehicle_incorporated_on,
        cast(source_reported_on as {{ dpf_type('date') }}) as vehicle_reported_on,
        cast(fund_business_key as {{ dpf_type('string') }}) as vehicle_fund_business_key
    from checked_pre_input
),
curation_records as (
    select
        vehicle_source_system,
        vehicle_identity_key,
        vehicle_normalised_name,
        vehicle_lei,
        vehicle_business_key,
        vehicle_record_id,
        vehicle_source_id,
        vehicle_fund_source_id,
        vehicle_parent_source_id,
        vehicle_name,
        vehicle_type,
        vehicle_jurisdiction,
        vehicle_incorporated_on,
        vehicle_reported_on,
        vehicle_fund_business_key,
        vehicle_identity_key as resolution_record_key
    from step_02_schema_transform
),
curation_edges as (
    select
        resolution_record_key,
        1 as key_rank,
        'vehicle_lei' as key_name,
        'vehicle_lei:' || vehicle_lei as key_value
    from curation_records
    where vehicle_lei is not null

    union all

    select
        resolution_record_key,
        2 as key_rank,
        'vehicle_normalised_name' as key_name,
        'vehicle_normalised_name:' || vehicle_normalised_name as key_value
    from curation_records
    where vehicle_normalised_name is not null
),
curation_labels_0 as (
    select distinct
        resolution_record_key,
        resolution_record_key as label
    from curation_edges
),
curation_values_1 as (
    select
        edges.key_value,
        min(labelled.label) as value_label
    from curation_edges as edges
    inner join curation_labels_0 as labelled
        on labelled.resolution_record_key = edges.resolution_record_key
    group by edges.key_value
),
curation_labels_1 as (
    select
        edges.resolution_record_key,
        min(matched.value_label) as label
    from curation_edges as edges
    inner join curation_values_1 as matched
        on matched.key_value = edges.key_value
    group by edges.resolution_record_key
),
curation_values_2 as (
    select
        edges.key_value,
        min(labelled.label) as value_label
    from curation_edges as edges
    inner join curation_labels_1 as labelled
        on labelled.resolution_record_key = edges.resolution_record_key
    group by edges.key_value
),
curation_labels_2 as (
    select
        edges.resolution_record_key,
        min(matched.value_label) as label
    from curation_edges as edges
    inner join curation_values_2 as matched
        on matched.key_value = edges.key_value
    group by edges.resolution_record_key
),
curation_components as (
    select
        resolution_record_key,
        label as component_id
    from curation_labels_2
),
curation_component_stats as (
    select
        component_id,
        count(*) as component_row_count
    from curation_components
    group by component_id
),
curation_component_keys as (
    select
        components.component_id,
        min(edges.key_rank) as best_key_rank
    from curation_components as components
    inner join curation_edges as edges
        on edges.resolution_record_key = components.resolution_record_key
    group by components.component_id
),
curation_resolved as (
    select
        records.vehicle_source_system,
        records.vehicle_identity_key,
        records.vehicle_normalised_name,
        records.vehicle_lei,
        records.vehicle_business_key,
        records.vehicle_record_id,
        records.vehicle_source_id,
        records.vehicle_fund_source_id,
        records.vehicle_parent_source_id,
        records.vehicle_name,
        records.vehicle_type,
        records.vehicle_jurisdiction,
        records.vehicle_incorporated_on,
        records.vehicle_reported_on,
        records.vehicle_fund_business_key,
        records.resolution_record_key,
        coalesce(components.component_id, records.resolution_record_key) as resolution_entity_key,
        coalesce(stats.component_row_count, 1) as resolution_row_count,
        case
            when keys.best_key_rank = 1 then 'vehicle_lei'
            when keys.best_key_rank = 2 then 'vehicle_normalised_name'
        end as resolution_key_name,
        case
            when coalesce(stats.component_row_count, 1) > 1 then 'deterministic'
            else 'unresolved'
        end as resolution_tier,
        coalesce(stats.component_row_count, 1) = 1 as resolution_pending
    from curation_records as records
    left join curation_components as components
        on components.resolution_record_key = records.resolution_record_key
    left join curation_component_stats as stats
        on stats.component_id = components.component_id
    left join curation_component_keys as keys
        on keys.component_id = components.component_id
)

select
